// This file is hand written and is not regenerated by `go generate
// ./internal/ent`: it is the PostgreSQL adapter behind OpenDatabase, and the only
// place this project names a PostgreSQL driver.
package ent

import (
	"net/url"

	"entgo.io/ent/dialect"

	// Registers the "postgres" database/sql driver this adapter names.
	// Until this file existed, lib/pq was a test-only dependency of this
	// module; a Walk-tier deployment is the first thing to need it at
	// run time, so internal/archtest's concrete-driver allowlist names it
	// alongside the SQLite driver.
	_ "github.com/lib/pq"
)

// The two interchangeable URL schemes libpq accepts for the same thing.
// Both are supported because both appear in the wild, and rejecting the
// longer spelling would be a gratuitous trap.
const (
	postgresURLScheme   = "postgres://"
	postgresqlURLScheme = "postgresql://"
)

// resolvePostgres builds the resolved DSN for a real PostgreSQL server.
//
// The DSN is passed to the driver verbatim. Unlike the SQLite adapter
// there is nothing to prepare: the database, its owner, and its network
// reachability are all the deployment's job, and a server this process
// cannot reach must surface as a connection error rather than as
// something this code tried to create.
func resolvePostgres(dsn string) resolvedDSN {
	return resolvedDSN{
		driver:   dialect.Postgres,
		dsn:      dsn,
		describe: describePostgresDSN(dsn),
	}
}

// describePostgresDSN renders a PostgreSQL DSN for an error message with
// any password stripped.
//
// This matters because OpenDatabase's errors are returned to composition roots
// that log them, and a DSN is the one configuration value on this path
// that routinely carries a credential inline. url.URL.Redacted replaces
// the password with "xxxxx" and leaves the rest legible, which is what
// makes the message useful for debugging without being unsafe to write
// down. A DSN that does not parse is described only by its scheme, since
// nothing can be assumed about where its secret sits.
func describePostgresDSN(dsn string) string {
	parsed, err := url.Parse(dsn)
	if err != nil {
		return "(unparseable postgres dsn)"
	}
	return parsed.Redacted()
}
